function validate([nums]) {
  if (nums.length < 2 || nums.length > 200000) return 'nums needs 2 to 200,000 values.';
  if (nums.some(v => v < 1 || v > 10000000)) return 'Each value is between 1 and 10^7.';
  return null;
}

