function maximumLength(nums) {
  let evens = 0;
  let odds = 0;
  let alternating = 0;
  let lastParity = -1;

  for (const num of nums) {
    const parity = num % 2;
    if (parity === 0) {
      evens++;
    } else {
      odds++;
    }
    if (parity !== lastParity) {
      alternating++;
      lastParity = parity;
    }
  }
  return Math.max(evens, odds, alternating);
}

