function maximumLength(nums) {
  // longest[i][r]: longest valid subsequence that ends at index i and whose neighbour sums all have parity r.
  // A single element has no sums, so it starts both kinds.
  const longest = nums.map(() => [1, 1]);
  let best = 1;
  for (let i = 0; i < nums.length; i++) {
    for (let j = 0; j < i; j++) {
      const r = (nums[j] + nums[i]) % 2;
      longest[i][r] = Math.max(longest[i][r], longest[j][r] + 1);
    }
    best = Math.max(best, longest[i][0], longest[i][1]);
  }
  return best;
}

