function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : int(2, 12);
  const top = size === 'large' || rand() < 0.3 ? 10000000 : 9;
  // Random parities, mostly even, mostly odd, or mostly alternating, so that each of the three shapes can win.
  const style = int(0, 3);
  const nums = [];
  let parity = int(0, 1);
  for (let i = 0; i < n; i++) {
    if (style === 0) parity = int(0, 1);
    else if (style === 1) parity = rand() < 0.8 ? 0 : 1;
    else if (style === 2) parity = rand() < 0.8 ? 1 : 0;
    else if (rand() < 0.75) parity = 1 - parity;
    let value = int(1, top);
    if (value % 2 !== parity) value = value === top ? value - 1 : value + 1;
    nums.push(value);
  }
  return [nums];
}
